"\"\"\"Distillation jacobienne — Construction des professeurs (parents).\n\nUn PROFESSEUR est un transformer de la même architecture que les élèves (tâche A de phase3_corpus),\ndont les matrices W1 des couches sont des tranches d'un champ de jacobiennes W*_l = J_{g*}(u*_l) :\n\n  - kind=\"gauss\" : g* = u + Σ_k a*_k φ_k(u), gaussiennes (famille du générateur élève — CONTRÔLE\n    POSITIF attendu : le générateur doit battre tout le monde, sa famille est la bonne) ;\n  - kind=\"mlp\"   : g* = V2·tanh(V1·u + b1) + b2, MLP quelconque (jacobiens analytiques\n    J = V2·diag(tanh′)·V1) — intégrable par construction mais HORS de la famille gaussienne\n    du générateur élève. C'est le cas test : la structure jacobienne est réelle, la\n    paramétrisation ne correspond pas.\n\nLes autres paramètres du parent (attention, W2, LN, embeddings) sont entraînés sur la tâche A\navec W1 figée aux tranches jacobiennes, si bien que le parent est un modèle compétent dont\nla structure des W1 est réellement un champ de jacobiennes.\n\nLe champ de points u*_l est une ligne bruitée (géométrie « vivante » de phase3_methods) : les\ncouches sont des échantillons ordonnés d'un même champ lisse — c'est ce que le générateur élève\npeut exploiter et que LoRA ne peut pas.\n\"\"\"\nimport numpy as np\n\nfrom phase3_model import Transformer\nfrom phase3_methods import _live_geometry, _v\nfrom phase3_corpus import get_task\nfrom distill_model import cosine_lr\n\nD, D_FF, L, H = 32, 64, 4, 2\nT, B = 32, 16\nPARENT_STEPS = 800\n\n\ndef make_field(kind, seed, d=D, d_ff=D_FF, L=L, K=8, alpha=0.5):\n    \"\"\"Construit (M*, points u*_l (L,d), W*_l (liste de L matrices (d_ff,d)), diagnostics).\n\n    W*_l = M* + s·(J_{g*}(u*_l) − I) pour le MLP (recentrage : le jacobien d'un MLP random\n    dévie de I ; on utilise la déviation J − I comme « perturbation » du champ, mise à\n    l'échelle pour que ‖W* − M‖_F ≈ alpha·‖M‖_F en moyenne, comme un générateur entraîné).\n    \"\"\"\n    rng = np.random.default_rng(31000 + seed)\n    geo = _live_geometry(d, d_ff, L, K, rng)\n    M, U = geo[\"M\"], geo[\"U\"]\n    if kind == \"gauss\":\n        C, logR, A = geo[\"C\"], geo[\"logR\"], rng.standard_normal((K, d_ff)) * 0.3\n        Ws = []\n        for l in range(L):\n            W = M.copy()\n            for k in range(K):\n                v, *_ = _v(U[l], C[k], float(np.exp(logR[k])))\n                W += np.outer(A[k], v)\n            Ws.append(W)\n    elif kind == \"mlp\":\n        h = 64\n        V1 = rng.standard_normal((h, d)) / np.sqrt(d)\n        b1 = rng.standard_normal(h) * 0.5\n        V2 = rng.standard_normal((d, h)) / np.sqrt(h)\n        b2 = np.zeros(d)\n\n        # jacobien analytique : g(u) = V2·tanh(V1 u + b1) + b2 ; J = V2·diag(tanh′)·V1\n        def g_jac(u):\n            pre = u @ V1.T + b1\n            tprime = 1 - np.tanh(pre) ** 2\n            return V2 @ (tprime[:, None] * V1)         # (d,d) = V2 (d,h) × diag (h) × V1 (h,d)\n\n        # projection E (d_ff, d) : h(u) = M·u + s·E·g*(u) ⇒ J_h = M + s·E·J_g* — champ\n        # jacobien de ℝ^d vers ℝ^{d_ff} (l'identité n'est définie que si d_ff = d)\n        E = rng.standard_normal((d_ff, d)) / np.sqrt(d)\n        Js = [g_jac(U[l]) for l in range(L)]\n        dev = [E @ J for J in Js]\n        # mise à l'échelle : ‖W*_l − M‖_F ≈ alpha·‖M‖_F\n        nM = np.linalg.norm(M)\n        scale = alpha * nM / np.mean([np.linalg.norm(dv) for dv in dev])\n        Ws = [M + scale * dv for dv in dev]\n    else:\n        raise ValueError(kind)\n    if kind == \"gauss\":\n        def Wstar(u):\n            W = M.copy()\n            for k in range(K):\n                v, *_ = _v(u, C[k], float(np.exp(logR[k])))\n                W += np.outer(A[k], v)\n            return W\n    else:\n        def Wstar(u):\n            pre = u @ V1.T + b1\n            tprime = 1 - np.tanh(pre) ** 2\n            J = V2 @ (tprime[:, None] * V1)\n            return M + scale * (E @ J)\n    diag = {\n        \"layer_dist\": [float(np.linalg.norm(Ws[l] - Ws[0]) / np.linalg.norm(Ws[0]))\n                       for l in range(1, L)],\n        \"dev_norm_frac\": [float(np.linalg.norm(Ws[l] - M) / np.linalg.norm(M)) for l in range(L)],\n    }\n    return {\"M\": M, \"U\": U, \"Ws\": [W.astype(np.float32) for W in Ws], \"kind\": kind,\n            \"diag\": diag, \"Wstar\": Wstar}\n\n\ndef build_parent(kind, seed, steps=PARENT_STEPS, verbose=False):\n    \"\"\"Entraîne les paramètres non-W1 du parent sur la tâche A, W1 figée aux tranches jacobiennes.\"\"\"\n    field = make_field(kind, seed)\n    train, val = get_task(\"a\", seed=0)\n    rng = np.random.default_rng(20000 + seed)\n    model = Transformer(train.V, D, D_FF, L, H, T, rng)\n    W1s = field[\"Ws\"]\n    Xval = val.eval_windows(T, 64)\n    for step in range(steps):\n        X = train.sample_batch(B, T, rng)\n        loss, cache = model.forward(X, W1s)\n        grads, _ = model.backward(cache, W1s)     # ∂L/∂W1 ignorée : W1 figée (champ jacobien)\n        model.step(grads, cosine_lr(step, steps))\n    parent_val = model.eval_loss(Xval, W1s)\n    res = {\"field\": field, \"parent_val\": parent_val,\n           \"parent_params\": {k: v for k, v in model.params.items()},\n           \"V\": train.V}\n    if verbose:\n        print(f\"[parent] {kind}/s{seed}: val CE = {parent_val:.4f} \"\n              f\"(uniforme = {np.log(train.V):.4f}), dist inter-couches = \"\n              f\"{np.mean(field['diag']['layer_dist']):.1%}\")\n    return res\n"